    # Initialize the salary list
    salaries = [i for i in range(1, n + 1)]

    # Initialize the dislike graph
    dislike_graph = {i: [] for i in range(1, n + 1)}
    for a, b in dislikes:
        dislike_graph[a].append(b)
        dislike_graph[b].append(a)

    # Initialize the dangerous triples counter
    dangerous_triples = 0

