    def brags(a, b):
        return b in dislike_graph[a]

    # Calculate initial dangerous triples
    for a in range(1, n + 1):
        for b in dislike_graph[a]:
            for c in dislike_graph[b]:
                if a != c and brags(a, b) and brags(b, c):
                    dangerous_triples += 1

    # Prepare the result list
    result = [dangerous_triples]

    # Process each salary revision
