        # Update the salary of the employee
        salaries[v_i - 1] = n + len(revisions)

        # Update the dislike graph
        for a in range(1, n + 1):
            dislike_graph[a].append(n + len(revisions))

        # Recalculate the dangerous triples
        new_dangerous_triples = 0
